def transform(grid):
    # Fill the horizontal spaces between matching colored endpoint bars,
    # while preserving the sparse diagonal marks and recoloring each to 4.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bar_color = g[0][-1] if all(x == g[0][-1] for x in g[0][-5:]) else g[-1][0]
    # Determine bar color by contiguous run(s) of same color at an outer edge.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1 and ((r == 0 and c >= w-5) or (r == h-1 and c < 5)):
                g[r][c] = 1
    # Background is the dominant value; marker is non-background/non-bar.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker_color = next((v for row in grid for v in row if v not in (bg, 1)), None)
    if marker_color is None:
        return g
    # Transform each diagonal ray of marker points: recolor marker and fill
    # from marker toward the nearest right boundary/bar with color 1.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color:
                g[r][c] = 4
                for x in range(c+1, w):
                    if grid[r][x] != bg:
                        break
                    g[r][x] = 1
    return g
