def transform(grid):
    # The color-7 edge stubs define horizontal rays; color-1 marker pixels
    # become 4 and extend rightward to the edge. Left stubs fill rightward too.
    g = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        # A 7 at the left edge launches a color-1 ray across that row.
        if grid[r][0] == 7:
            for c in range(1, w):
                if grid[r][c] == 7:
                    break
                g[r][c] = 1
        # Each isolated 1 marker changes to 4 and fills to the right,
        # stopping at a non-background boundary such as the 7 stub.
        for c in range(w):
            if grid[r][c] == 1:
                g[r][c] = 4
                for x in range(c + 1, w):
                    if grid[r][x] != 0:
                        break
                    g[r][x] = 1
    return g
