def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Colored edge cells launch rays perpendicular to that edge. Rays paint 1;
    # a non-background object encountered in the interior is a stop marker (4).
    rays = []
    for c in range(w):
        if grid[0][c] != bg:
            rays.append((0, c, 1, 0))
        if h > 1 and grid[h-1][c] != bg:
            rays.append((h-1, c, -1, 0))
    for r in range(h):
        if grid[r][0] != bg:
            rays.append((r, 0, 0, 1))
        if w > 1 and grid[r][w-1] != bg:
            rays.append((r, w-1, 0, -1))
    for r, c, dr, dc in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            val = grid[rr][cc]
            if val != bg:
                g[rr][cc] = 4
                break
            g[rr][cc] = 1
            rr += dr
            cc += dc
    return g
