def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Infer background as the overwhelmingly repeated field color.
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    top = [c for c, x in enumerate(grid[0]) if x != bg]
    bottom = [c for c, x in enumerate(grid[-1]) if x != bg]
    if not top or not bottom or len(top) != len(bottom):
        return out
    # For each distinct interior color, project points aligned with one edge
    # segment inward, and copy their segment-relative column to the opposite edge.
    edge_colors = {grid[0][c] for c in top} | {grid[-1][c] for c in bottom}
