    left = [r for r in range(h) if grid[r][0] != bg]
    right = [r for r in range(h) if grid[r][-1] != bg]
    edge_colors = {grid[0][c] for c in top} | {grid[-1][c] for c in bottom}
    edge_colors |= {grid[r][0] for r in left} | {grid[r][-1] for r in right}
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in edge_colors]

    # Opposing horizontal edge segments: a marker aligned with one run paints
    # toward that edge and projects its offset as a full stripe from the other.
    if top and bottom:
        t0, b0 = min(top), min(bottom)
        for r, c, color in markers:
