                out[r][c] = 4
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] != bg: break
                    out[rr][c] = color
                tc = t0 + c - b0
                if tc < t0 + len(top):
                    for rr in range(1, h - 1): out[rr][tc] = color
            elif t0 <= c < t0 + len(top):
                out[r][c] = 4
                for rr in range(r - 1, 0, -1):
                    if grid[rr][c] != bg: break
                    out[rr][c] = color
                tc = b0 + c - t0
                if tc < b0 + len(bottom):
                    for rr in range(1, h - 1): out[rr][tc] = color

