    if left and right:
        l0, r0 = min(left), min(right)
        for r, c, color in markers:
            if l0 <= r < l0 + len(left):
                out[r][c] = 4
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] != bg: break
                    out[r][cc] = color
                tr = r0 + r - l0
                if tr < r0 + len(right):
                    for cc in range(1, w - 1): out[tr][cc] = color
            elif r0 <= r < r0 + len(right):
                out[r][c] = 4
                for cc in range(c - 1, 0, -1):
                    if grid[r][cc] != bg: break
                    out[r][cc] = color
                tr = l0 + r - r0
                if tr < l0 + len(left):
                    for cc in range(1, w - 1): out[tr][cc] = color
    return out
