def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Border runs indicate ray directions. Each interior dot changes to 4;
    # its color fills straight toward the nearest aligned colored border run.
    borders = []
    for c in range(w):
        if grid[0][c] != bg: borders.append((0, c, 1, 0))
        if grid[h-1][c] != bg: borders.append((h-1, c, -1, 0))
    for r in range(h):
        if grid[r][0] != bg: borders.append((r, 0, 0, 1))
        if grid[r][w-1] != bg: borders.append((r, w-1, 0, -1))
    edgecolors = {grid[r][c] for r,c,_,_ in borders}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in edgecolors: continue
            out[r][c] = 4
            # choose the nearest border stub on the same row or column
            candidates = []
            for br,bc,dr,dc in borders:
                if (dr == 0 and br == r) or (dc == 0 and bc == c):
                    dist = abs(br-r) + abs(bc-c)
                    if dist: candidates.append((dist,br,bc,dr,dc))
            if not candidates: continue
            _,br,bc,dr,dc = min(candidates)
            step_r = 1 if br > r else -1 if br < r else 0
            step_c = 1 if bc > c else -1 if bc < c else 0
            rr,cc = r+step_r,c+step_c
            while (rr,cc) != (br,bc):
                if grid[rr][cc] != bg: break
                out[rr][cc] = color
                rr += step_r; cc += step_c
    return out
