def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    top = [c for c, v in enumerate(grid[0]) if v != bg]
    bottom = [c for c, v in enumerate(grid[-1]) if v != bg]
    if not top or not bottom:
        return out
    t0, b0 = min(top), min(bottom)
    edge_colors = {grid[0][c] for c in top} | {grid[-1][c] for c in bottom}
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in edge_colors:
                continue
            out[r][c] = 4
            if b0 <= c < b0 + len(bottom):
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] != bg:
                        break
                    out[rr][c] = color
                paired = t0 + c - b0
                if paired < t0 + len(top):
                    for rr in range(1, h - 1):
                        out[rr][paired] = color
    return out
