def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    bottom_cols = {c for c, v in enumerate(grid[-1]) if v != bg}
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] == 3 and c in bottom_cols:
                out[r][c] = 4
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] != bg:
                        break
                    out[rr][c] = 3
    return out
